import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.BM5YPQmL.js";const c=JSON.parse('{"title":"درس السياحة والسفر","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/tutorials/tourism.md","filePath":"ar/guide/tutorials/tourism.md"}'),l={name:"ar/guide/tutorials/tourism.md"};function r(n,a,h,o,d,p){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="درس-السياحة-والسفر" tabindex="-1">درس السياحة والسفر <a class="header-anchor" href="#درس-السياحة-والسفر" aria-label="Permalink to &quot;درس السياحة والسفر&quot;">​</a></h1><p>في هذا الدرس تصنع فيديو موضوعه: برنامج ثلاثة أيام في بلدة ساحلية خيالية. ستستخدم الحزمة <code>tourism</code> وثيمها <code>voyage</code>، ويستغرق العمل نحو عشر دقائق قبل التسجيل.</p><h2 id="_1-أنشئ-الحلقة" tabindex="-1">1. أنشئ الحلقة <a class="header-anchor" href="#_1-أنشئ-الحلقة" aria-label="Permalink to &quot;1. أنشئ الحلقة&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> three-days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tourism</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> itinerary-3-days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ar</span></span></code></pre></div><p>استخدم <code>--lang en</code> لنسخة إنجليزية. وتضم الحزمة أيضاً القالبين <code>airport-to-town</code> و<code>best-time-to-visit</code>. يعرض <a href="./../../reference/packs.html#tourism">فهرس الحزم</a> كل القوالب وحقولها.</p><h2 id="_2-أدخل-بياناتك" tabindex="-1">2. أدخل بياناتك <a class="header-anchor" href="#_2-أدخل-بياناتك" aria-label="Permalink to &quot;2. أدخل بياناتك&quot;">​</a></h2><p>افتح الحلقة بالأمر <code>reelforge edit three-days</code> واستبدل الأسماء والأرقام والكلمة المفتاحية الافتراضية ببياناتك، أو ابدأ من لوحة التحكم (<strong>+ New episode</strong> ثم <strong>Start from template</strong>)، فيطلب النموذج كل حقل على حدة. التزم بحدود الطول الظاهرة لكل حقل.</p><p><strong>الجمهور والنبرة.</strong> المسافرون الذين يخططون لرحلة والزوار في المكان. كن جذاباً وعملياً.</p><ul><li>استخدم <code>timeline</code> للأيام و<code>chip</code> لكل محطة.</li><li>قدّم نصيحة عملية واحدة لكل يوم (المواصلات أو التوقيت أو التذاكر).</li><li>اختم بسؤال يدعو إلى التعليق، مثل المحطة التي يريدها المشاهد في الحلقة القادمة.</li></ul><h2 id="_3-راجع-المحتوى" tabindex="-1">3. راجع المحتوى <a class="header-anchor" href="#_3-راجع-المحتوى" aria-label="Permalink to &quot;3. راجع المحتوى&quot;">​</a></h2><ul><li>لا فنادق ولا شركات طيران ولا منظمي رحلات ولا منصات حجز حقيقية.</li><li>الأسعار والمواعيد وقواعد التأشيرة كما تُقدَّم فقط، مع عبارة «تحقق قبل السفر».</li><li>احترم الثقافة المحلية والأماكن المقدسة، ولا قوالب نمطية.</li></ul><h2 id="_4-تحقق-وسجّل-وصدّر" tabindex="-1">4. تحقق وسجّل وصدّر <a class="header-anchor" href="#_4-تحقق-وسجّل-وصدّر" aria-label="Permalink to &quot;4. تحقق وسجّل وصدّر&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> three-days</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> three-days</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # after you save voice.wav in the episode folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> render</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> three-days</span></span></code></pre></div><p>يوجد مثال مكتمل في <code>packs/tourism/examples/azur-bay-ar</code>؛ صدّره مع الخيار <code>--silent</code> للمقارنة.</p>`,14)])])}const g=s(l,[["render",r]]);export{c as __pageData,g as default};
